import {createWeeklyExam} from './weekly-exam.mjs';
import {renderWeekly} from './practice-weekly.mjs';
import {createPracticeCalendar} from './practice-calendar.mjs';
import {renderSpacing} from './prediction-spacing.mjs';
import {adaptPrediction,levelLabels,renderProgressChart} from './prediction-adaptive.mjs';
import {createProgressStore,signalStats} from './prediction-progress.mjs';
import {buildComparison} from './comparison-model.mjs';
import {predictionEvents,signals} from './prediction-model.mjs';
import {createPrediction,predictionAnswer,predictionHint,predictionScore} from './prediction-model.mjs';
export function createPredictionUI({experiment,seek,resume,refresh,ready,loadExperiment}){
 const root=document.querySelector('#guided'),q=s=>root.querySelector(s);let game=null,review=false,record=null,historyDirty=true,spacingStamp='';let storage;try{storage=localStorage;}catch{storage={getItem(){throw Error();}};}const store=createProgressStore(storage);
 root.innerHTML='<div class="actions"><h2>Predice el siguiente scan</h2><button id="guideStart">Iniciar modo guiado</button><button id="guideExit" hidden>Salir del modo guiado</button></div><p>Marcha está solicitada en ambos bancos desde el inicio. Pausamos 20 ms antes de cada cambio de sensores, salidas o contactos supervisados (RUN válido, P01 y T1–T4.Q). Elige una señal que cambiará en el banco indicado: solo una de las opciones es correcta. Las opciones y la orientación se adaptan a tu progreso por señal. Puede haber otros cambios simultáneos.</p><p>Por pregunta: 100 puntos, −20 por error y −10 por pista (máximo dos). Consultar solución vale 0. La nota es la media de las preguntas resueltas, sin premio por rapidez. Resultados guardados en este navegador, sin sincronización entre dispositivos.</p><div id="guideBody" hidden><p id="guideProgress"></p><h3 id="guideQuestion"></h3><div id="guideChoices" class="actions"></div><div class="actions"><button id="guideHint">Pista</button><button id="guideReveal">Ver solución</button><button id="guideNext" hidden>Continuar hasta el próximo cambio</button></div><p id="guideHintText"></p><p id="guideFeedback" role="status"></p><ul id="guideChanges"></ul></div>';

 const history=document.createElement('section');history.className='prediction-history';root.after(history);history.innerHTML='<h2>Tu progreso y repaso</h2><p id="progressNotice"></p><p id="progressSummary"></p><button id="reviewWeak">Repasar mis dificultades</button><p>Las dificultades se atribuyen a la señal que había que predecir. Errores = intentos fallidos; cada pregunta cuenta una vez aunque uses varias pistas. El repaso prioriza errores, pistas y soluciones consultadas. Conservamos las últimas 500 preguntas, incluidas las pendientes.</p><section id="weeklyReport" aria-label="Resumen semanal y plan de repaso"></section><section id="practiceCalendar" aria-label="Calendario y meta diaria"></section><section id="spacedReview" aria-label="Repasos espaciados para hoy"></section><section id="progressChart" aria-label="Gráfica de progreso por señal"></section><p>Adaptación por señal: con menos de 3 respuestas resueltas, nivel Apoyo. En las últimas 5, media ≥65 activa Práctica; media ≥85 y al menos 3 respuestas sin ayuda activa Reto. Si los resultados bajan, vuelve el apoyo. No cambia la velocidad del circuito. Las dos pistas siguen disponibles en todos los niveles.</p><div class="history-scroll"><table><thead><tr><th>Señal objetivo</th><th>Preguntas</th><th>Errores</th><th>Pistas</th><th>Soluciones</th><th>Media</th><th>Sin ayuda</th><th>Repaso</th></tr></thead><tbody id="signalRows"></tbody></table></div><details><summary>Últimos resultados</summary><ol id="questionHistory"></ol></details>';
 const h=s=>history.querySelector(s);const calendar=createPracticeCalendar(h('#practiceCalendar'),storage);
 function renderHistory(){history.hidden=!!game;if(game)return;const stamp=new Date().toDateString()+':'+ready();if(historyDirty||stamp!==spacingStamp){spacingStamp=stamp;calendar.update({onChange:()=>{historyDirty=true;renderHistory();},rows:store.rows(),ready:ready(),start:startReview,startFresh:()=>q('#guideStart').click()});renderWeekly(h('#weeklyReport'),store.rows(),calendar.state(),{ready:ready(),start:startReview,startFresh:()=>q('#guideStart').click()});renderSpacing(h('#spacedReview'),store.rows(),{ready:ready(),start:startReview});}if(!historyDirty){history.querySelectorAll('#signalRows button').forEach(b=>b.disabled=!ready());h('#reviewWeak').disabled=!ready()||!signalStats(store.rows()).some(s=>s.priority>0);return;}historyDirty=false;const rows=store.rows(),stats=signalStats(rows),resolved=rows.filter(r=>r.resolved);renderProgressChart(h('#progressChart'),rows);h('#progressNotice').textContent=store.warning()||'Guardado local automático después de cada intento, pista y respuesta. Recargar conserva los resultados; las preguntas pendientes no cuentan en la media.';h('#progressSummary').textContent=resolved.length+' resueltas · '+(rows.length-resolved.length)+' pendientes · Media '+(resolved.length?Math.round(resolved.reduce((n,r)=>n+r.points,0)/resolved.length):'—')+'/100';h('#signalRows').replaceChildren();for(const s of stats){const tr=document.createElement('tr');for(const v of [s.label,s.questions,s.errors,s.hints,s.reveals,s.mean===null?'—':s.mean+'/100',s.clean]){const td=document.createElement('td');td.textContent=v;tr.append(td);}const td=document.createElement('td'),b=document.createElement('button');b.textContent='Practicar';b.disabled=!ready();b.onclick=()=>startReview([s.signal]);td.append(b);tr.append(td);h('#signalRows').append(tr);}h('#questionHistory').replaceChildren();for(const r of rows.slice(-20).reverse()){const li=document.createElement('li');li.textContent=new Date(r.date).toLocaleString('es-CO')+' · '+r.label+' · '+r.kind+' · '+(r.review?'Repaso · ':'')+(r.exam?'Examen · ':r.level?levelLabels[r.level]+' · ':'')+(r.resolved?r.points+'/100':'Pendiente')+' · '+r.errors+' errores · '+r.hints+' pistas'+(r.wrong.length?' · Elegiste: '+r.wrong.join(', '):'');h('#questionHistory').append(li);}h('#reviewWeak').disabled=!ready()||!stats.some(s=>s.priority>0);}
 function beginRecord(){game.events[game.at]=adaptPrediction(game.events[game.at],store.rows());const e=game.events[game.at];record={id:crypto.randomUUID(),date:new Date().toISOString(),kind:e.kind||experiment().kind,signal:e.answer.id,label:e.answer.label,errors:0,hints:0,revealed:false,resolved:false,points:0,wrong:[],review,level:e.level,sourceExam:e.sourceExam||null,sourceQuestion:e.sourceQuestion??null};q('#guideChoices').dataset.key='';saveRecord();}
 function saveRecord(){if(!record)return;record.errors=game.attempts;record.hints=game.hints;store.save(record);historyDirty=true;}
 function startReview(ids){const candidates=[];for(const kind of ['pressure','jam','sensor','pressureWave','combined'])for(const event of predictionEvents(buildComparison(kind))){for(const answer of event.changes.filter(c=>ids.includes(c.id))){const wrong=signals.filter(o=>!event.changes.some(c=>c.bank===answer.bank&&c.id===o.id)).slice(0,3).map(({id,label,type})=>({id,label,type}));const options=[...wrong];options.splice(event.index%4,0,{id:answer.id,label:answer.label,type:answer.type});if(wrong.length)candidates.push({...event,bank:answer.bank,answer,options,kind});}}const buckets=ids.map(id=>candidates.filter(e=>e.answer.id===id)),queue=[];while(queue.length<8&&buckets.some(b=>b.length))for(const b of buckets)if(b.length&&queue.length<8)queue.push(b.shift());if(!queue.length)return;review=true;game={events:queue.slice(0,8),at:0,phase:'question',attempts:0,hints:0,results:[],feedback:''};loadExperiment(game.events[0].kind);beginRecord();seek(game.events[0].index-1);}
 h('#reviewWeak').onclick=()=>startReview(signalStats(store.rows()).filter(s=>s.priority>0).slice(0,3).map(s=>s.signal));
 const examHost=document.createElement('section');examHost.className='weekly-exam';root.after(examHost);const exam=createWeeklyExam(examHost,{storage,ready,loadExperiment,seek,refresh,startExact:events=>{review=true;game={events,at:0,phase:'question',attempts:0,hints:0,results:[],feedback:''};loadExperiment(events[0].kind);beginRecord();seek(events[0].index-1);},save:r=>store.save(r),onSaved:()=>{historyDirty=true;}});
 function render(){examHost.hidden=!!game;exam.render();root.hidden=exam.active();if(exam.active()){history.hidden=true;return;}renderHistory();q('#guideStart').disabled=!ready();q('#guideStart').hidden=!!game;q('#guideExit').hidden=!game;q('#guideBody').hidden=!game;if(!game)return;const e=game.events[game.at],done=game.phase==='complete',answer=game.phase==='answer';q('#guideProgress').textContent=(review?'REPASO · ':'')+'Resueltas '+game.results.length+' / '+game.events.length+' · Nota '+predictionScore(game)+'/100 · Errores esta pregunta: '+game.attempts+' · Pistas: '+game.hints+(!done?' · '+levelLabels[e.level]:'')+(store.warning()?' · '+store.warning():'');
 q('#guideQuestion').textContent=done?'Recorrido completado. Revisa las diferencias en modo libre.':game.phase==='travel'?'Observa cómo avanza el proceso…':'Banco '+(e.bank==='fault'?'con fallo':'normal')+(e.level==='advanced'?' · ¿Qué señal cambiará y en qué sentido en el scan de ':' · ¿Qué cambiará en el scan de ')+(e.index*.02).toFixed(2)+' s?';
 const key=game.at+':'+game.phase;if(q('#guideChoices').dataset.key!==key){q('#guideChoices').dataset.key=key;if(game.phase==='question'){q('#guideQuestion').tabIndex=-1;q('#guideQuestion').focus({preventScroll:true});root.scrollIntoView({block:'center'});}q('#guideChoices').replaceChildren();if(game.phase==='question')for(const option of e.options){const b=document.createElement('button');b.textContent=option.label;b.onclick=()=>answerWith(option.id);q('#guideChoices').append(b);}}
 q('#guideHint').hidden=q('#guideReveal').hidden=game.phase!=='question';q('#guideHint').disabled=game.hints>=2;q('#guideNext').hidden=!answer;
 q('#guideHintText').textContent=game.phase==='question'&&game.hints?(game.hints===1?'Pista 1: tipo de señal: '+e.answer.type+'. Compara posición, entradas y etapa actual.':'Pista 2: la señal pasará de '+e.answer.from+' a '+e.answer.to+'. '+(e.answer.type==='salida'?'Revisa el permiso RUN y la etapa que escribe las bobinas.':e.answer.type==='sensor'?'Observa extremos del pistón y presión; una conexión intermitente puede cambiar sin movimiento.':'Revisa las condiciones lógicas y el tiempo acumulado de los TON.')):'';
 q('#guideFeedback').textContent=(game.phase==='question'&&e.level==='support'?'Orientación: busca una señal de tipo '+e.answer.type+'. ':'')+game.feedback;q('#guideChanges').replaceChildren();if(answer)for(const c of e.changes){const li=document.createElement('li');li.textContent=(c.bank==='fault'?'Con fallo':'Normal')+' · '+c.label+': '+c.from+' → '+c.to;q('#guideChanges').append(li);}if(answer){const li=document.createElement('li');li.textContent='La imagen ya muestra el scan resuelto. Las entradas se leen antes de evaluar el ladder; las salidas se escriben al final. El movimiento responde en el scan siguiente.';q('#guideChanges').append(li);}}
 function answerWith(id,reveal=false){if(!game||game.phase!=='question')return;const ok=predictionAnswer(game,id,reveal);if(ok){const result=game.results.at(-1);record.resolved=true;record.completedAt=new Date().toISOString();record.points=result.points;record.revealed=result.revealed;}else{const option=game.events[game.at].options.find(o=>o.id===id);if(option)record.wrong.push(option.label);}saveRecord();if(ok)seek(game.events[game.at].index);else render();}
 q('#guideStart').onclick=()=>{review=false;game=createPrediction(experiment());beginRecord();seek(game.events[0].index-1);};
 q('#guideExit').onclick=()=>{game=null;refresh();};q('#guideHint').onclick=()=>{predictionHint(game);saveRecord();render();};q('#guideReveal').onclick=()=>answerWith(null,true);
 q('#guideNext').onclick=()=>{game.at++;game.attempts=game.hints=0;game.feedback='';if(game.at>=game.events.length){game.phase='complete';refresh();return;}beginRecord();if(review){loadExperiment(game.events[game.at].kind);game.phase='question';seek(game.events[game.at].index-1);}else{game.phase='travel';resume();}};
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)renderHistory();});setInterval(()=>{if(!document.hidden)renderHistory();},60000);
 return {active:()=>!!game||exam.active(),examTesting:()=>exam.testing(),render,limit(next){if(!game||game.phase!=='travel')return next;const boundary=game.events[game.at].index-1;if(next>=boundary){game.phase='question';return boundary;}return next;},waiting:()=>exam.active()||!!game&&game.phase!=='travel',state:()=>game,examState:()=>exam.state()};
}
